using System;using System.IO;using System.Linq;using System.Web.Script.Serialization;using EnhancedZune;
class LegacyMapping {public string id=null,name=null;}
class LegacyTests {
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static int Main(string[] args){try{string root=Path.GetFullPath(args[0]);Directory.CreateDirectory(root);Engine.Testing=true;Engine.TestRoot=root;var map=new JavaScriptSerializer().Deserialize<LegacyMapping[]>(File.ReadAllText(args[2]));using(var current=new Bundle())foreach(string resource in new[]{"rc1.zip","rc2.zip","rc3.zip","rc4.zip","rc5.zip"})using(var old=new Bundle(false,resource)){
  string target=Path.Combine(root,old.M.version);Directory.CreateDirectory(target);foreach(string name in old.M.dependencies.Select(x=>x.name).Concat(old.M.files.Where(x=>x.kind=="delta").Select(x=>x.name))){var row=map.Single(x=>x.name==name);File.Copy(Path.Combine(args[1],row.id),Path.Combine(target,name));}
  string backup=Engine.Install(target,old,delegate{});bool refused=false;try{Engine.Install(target,current,delegate{});}catch(IOException ex){refused=ex.Message.Contains("Restore originals first");}Check(refused,"Earlier version was not identified safely: "+old.M.version);Check(Engine.State(target,old.M)=="Enhanced","Refusal changed earlier files");Engine.RestoreKnown(target,backup,current,delegate{});Check(Engine.State(target,current.M)=="Original","Earlier version recovery did not restore originals");Console.WriteLine("PASS RC6 restores verified "+old.M.version+" backup and recognizes originals");
  string reinstallBackup=Engine.Install(target,old,delegate{});foreach(var entry in old.M.files.Where(x=>x.kind=="delta"))File.Copy(Path.Combine(reinstallBackup,entry.name),Path.Combine(target,entry.name),true);
  Engine.Install(target,current,delegate{});Check(Engine.State(target,current.M)=="Enhanced","Original reinstall with earlier helper leftovers was not recovered");Check(Engine.Load(reinstallBackup).status=="Restored","Earlier verified recovery journal not completed");Console.WriteLine("PASS original reinstall with "+old.M.version+" helper leftovers recovers and installs current enhancements");
 }File.WriteAllText(Path.Combine(root,"results.json"),"{\"status\":\"passed\",\"rc1_rc2_rc3_rc4_rc5_recovery\":true,\"reinstalled_originals_with_earlier_helpers\":true}");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
